-- 1. Create the Table
CREATE TABLE IF NOT EXISTS public.menu_items (
    id text PRIMARY KEY,
    name_tr text,
    name_en text,
    name_ar text,
    name_zh text,
    description_tr text,
    description_en text,
    description_ar text,
    description_zh text,
    ingredients text[],
    portion_or_pieces text,
    price numeric,
    currency text DEFAULT 'TL',
    category text,
    tags text[],
    allergens text[],
    image text,
    availability boolean DEFAULT true,
    last_reviewed_at text
);

-- 2. Clear existing data (if you want to re-run this script)
